import json, os, shutil, sqlite3
from pathlib import Path

base = Path('/home/user/.config/google-chrome/Default')
cache_base = Path('/home/user/.cache/google-chrome')
terms = ['amazon', 'a2z', 'audible', 'imdb']
like_terms = [f'%{t}%' for t in terms]
summary = {'sqlite_rows_deleted': 0, 'sqlite_dbs_touched': [], 'paths_removed': [], 'prefs_entries_removed': 0}

def db_tables(conn):
    return [r[0] for r in conn.execute(\"SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'\")]

def clean_sqlite(path):
    if not path.exists(): return
    deleted = 0
    try:
        conn = sqlite3.connect(str(path))
        conn.execute('PRAGMA foreign_keys=OFF')
        for table in db_tables(conn):
            try:
                cols = conn.execute(f'PRAGMA table_info(\"{table}\")').fetchall()
                text_cols = [c[1] for c in cols if (c[2] or '').upper() in ('', 'TEXT', 'VARCHAR', 'CHAR') or any(x in c[1].lower() for x in ('url','host','domain','origin','site','title','keyword','term'))]
                if not text_cols:
                    continue
                clauses=[]; params=[]
                for col in text_cols:
                    for pat in like_terms:
                        clauses.append(f'lower(CAST(\"{col}\" AS TEXT)) LIKE ?')
                        params.append(pat)
                before = conn.total_changes
                conn.execute(f'DELETE FROM \"{table}\" WHERE ' + ' OR '.join(clauses), params)
                deleted += conn.total_changes - before
            except Exception:
                pass
        conn.commit()
        if deleted:
            try: conn.execute('VACUUM')
            except Exception: pass
            summary['sqlite_dbs_touched'].append(str(path))
            summary['sqlite_rows_deleted'] += deleted
        conn.close()
    except Exception as e:
        print(f'skipped sqlite {path}: {e}')

for name in ['Cookies','History','Favicons','Top Sites','Shortcuts','Network Action Predictor','Reporting and NEL','Trust Tokens','DIPS','WebStorage/QuotaManager']:
    clean_sqlite(base / name)

# Remove Chrome cache wholesale; cache is not user data and avoids stale Amazon ad/assets entries.
for p in [cache_base / 'Default', base / 'GPUCache', base / 'DawnCache', base / 'Code Cache', base / 'Cache', base / 'Media Cache']:
    if p.exists():
        shutil.rmtree(p, ignore_errors=True)
        summary['paths_removed'].append(str(p))

# Remove session state and service worker storage so Amazon tabs/workers cannot be restored.
for p in [base / 'Sessions', base / 'Session Storage', base / 'Service Worker']:
    if p.exists():
        shutil.rmtree(p, ignore_errors=True)
        summary['paths_removed'].append(str(p))

# CDP clears logical Local Storage, but LevelDB logs can retain old deleted keys. Remove only this storage bucket.
for p in [base / 'Local Storage' / 'leveldb', base / 'IndexedDB' / 'https_www.amazon.com_0.indexeddb.leveldb']:
    if p.exists():
        shutil.rmtree(p, ignore_errors=True)
        summary['paths_removed'].append(str(p))

# Clean content-setting/site permission exceptions and other preference strings mentioning Amazon-owned sites.
def contains_term(x):
    return isinstance(x, str) and any(t in x.lower() for t in terms)

def scrub(obj):
    removed = 0
    if isinstance(obj, dict):
        for k in list(obj.keys()):
            v = obj[k]
            if contains_term(k) or contains_term(v):
                del obj[k]; removed += 1
            else:
                r = scrub(v); removed += r
                if isinstance(v, (dict, list)) and not v and contains_term(k):
                    del obj[k]; removed += 1
    elif isinstance(obj, list):
        new=[]
        for v in obj:
            if contains_term(v):
                removed += 1
            else:
                removed += scrub(v); new.append(v)
        obj[:] = new
    return removed

pref = base / 'Preferences'
if pref.exists():
    try:
        data = json.loads(pref.read_text())
        removed = scrub(data)
        if removed:
            pref.write_text(json.dumps(data, separators=(',', ':')))
            summary['prefs_entries_removed'] = removed
    except Exception as e:
        print(f'skipped Preferences: {e}')

print(json.dumps(summary, indent=2))
PY"

